<?php require '../config/db.php';require '../includes/functions.php';$blog=(int)($_POST['blog_id']??0);$reaction=$_POST['reaction']??'';$tok=client_token();if(!$blog||!in_array($reaction,['like','dislike']))json_response(false,'Invalid reaction.',[],422);$q=$pdo->prepare('SELECT id,reaction FROM blog_reactions WHERE blog_id=? AND visitor_token=? LIMIT 1');$q->execute([$blog,$tok]);$x=$q->fetch();if($x){if($x['reaction']===$reaction)json_response(false,'You already submitted this reaction.');$pdo->prepare('UPDATE blog_reactions SET reaction=? WHERE id=?')->execute([$reaction,$x['id']]);json_response(true,'Your reaction was updated.');}$pdo->prepare('INSERT INTO blog_reactions(blog_id,visitor_token,reaction) VALUES(?,?,?)')->execute([$blog,$tok,$reaction]);json_response(true,'Thanks for your feedback.');